interface VerticalScrollPickerProps {
  value: number;
  onChange: (val: number) => void;
  min: number;
  max: number;
  label: string;
}

const VerticalScrollPicker: React.FC<VerticalScrollPickerProps> = ({ value, onChange, min, max, label }) => {
  const [isDragging, setIsDragging] = useState(false);
  const startY = React.useRef(0);
  const startValue = React.useRef(0);

  const handleMouseDown = (e: React.MouseEvent) => {
    setIsDragging(true);
    startY.current = e.clientY;
    startValue.current = value;
  };

  const handleMouseMove = (e: React.MouseEvent) => {
    if (!isDragging) return;
    const deltaY = startY.current - e.clientY;
    const step = Math.round(deltaY / 15);
    let newValue = startValue.current + step;
    if (newValue < min) newValue = min;
    if (newValue > max) newValue = max;
    if (newValue !== value) {
      onChange(newValue);
    }
  };

  const handleMouseUpOrLeave = () => {
    setIsDragging(false);
  };

  const handleTouchStart = (e: React.TouchEvent) => {
    setIsDragging(true);
    startY.current = e.touches[0].clientY;
    startValue.current = value;
  };

  const handleTouchMove = (e: React.TouchEvent) => {
    if (!isDragging) return;
    const deltaY = startY.current - e.touches[0].clientY;
    const step = Math.round(deltaY / 15);
    let newValue = startValue.current + step;
    if (newValue < min) newValue = min;
    if (newValue > max) newValue = max;
    if (newValue !== value) {
      onChange(newValue);
    }
  };

  const increment = () => {
    if (value < max) onChange(value + 1);
  };

  const decrement = () => {
    if (value > min) onChange(value - 1);
  };

  const handleWheel = (e: React.WheelEvent) => {
    if (e.deltaY < 0) {
      if (value < max) onChange(value + 1);
    } else {
      if (value > min) onChange(value - 1);
    }
  };

  const getVisibleNumbers = () => {
    const nums = [];
    for (let i = -2; i <= 2; i++) {
      const v = value + i;
      if (v >= min && v <= max) {
        nums.push({ val: v, offset: i });
      } else {
        nums.push({ val: null, offset: i });
      }
    }
    return nums;
  };

  return (
    <div 
      className="flex flex-col items-center select-none"
      onWheel={handleWheel}
    >
      <span className="text-[10px] font-black text-white/40 mb-1">{label}</span>
      <div 
        className={`w-20 h-28 bg-[#090D1E]/90 border ${isDragging ? 'border-purple-500 shadow-[0_0_15px_rgba(168,85,247,0.25)]' : 'border-white/5'} rounded-2xl flex flex-col items-center justify-between py-1 relative overflow-hidden transition-all touch-none cursor-ns-resize`}
        onMouseDown={handleMouseDown}
        onMouseMove={handleMouseMove}
        onMouseUp={handleMouseUpOrLeave}
        onMouseLeave={handleMouseUpOrLeave}
        onTouchStart={handleTouchStart}
        onTouchMove={handleTouchMove}
        onTouchEnd={handleMouseUpOrLeave}
      >
        <div className="absolute top-0 left-0 right-0 h-8 bg-gradient-to-b from-[#090D1E] to-transparent pointer-events-none z-10" />
        <div className="absolute bottom-0 left-0 right-0 h-8 bg-gradient-to-t from-[#090D1E] to-transparent pointer-events-none z-10" />

        <button 
          type="button"
          onClick={(e) => { e.stopPropagation(); increment(); }}
          className="text-white/30 hover:text-purple-400 p-1 transition-colors z-20 cursor-pointer"
        >
          <svg className="w-3.5 h-3.5" fill="none" viewBox="0 0 24 24" stroke="currentColor">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M5 15l7-7 7 7" />
          </svg>
        </button>

        <div className="flex-1 flex flex-col justify-center items-center relative h-12 w-full">
          <div className="absolute inset-y-2 inset-x-1 border-y border-purple-500/30 bg-purple-500/5 pointer-events-none rounded" />

          <div className="flex flex-col items-center justify-center gap-1 py-0.5">
            {getVisibleNumbers().map((item, idx) => {
              if (item.val === null) {
                return <div key={`empty-${idx}`} className="h-4 w-4" />;
              }
              const isActive = item.offset === 0;
              return (
                <div 
                  key={`num-${item.val}-${idx}`}
                  onClick={(e) => { e.stopPropagation(); onChange(item.val as number); }}
                  className={`text-center transition-all duration-150 cursor-pointer ${
                    isActive 
                      ? "text-purple-400 font-extrabold text-sm scale-110 drop-shadow-[0_0_8px_rgba(168,85,247,0.5)]" 
                      : "text-white/20 font-bold text-[10px]"
                  }`}
                >
                  {item.val}
                </div>
              );
            })}
          </div>
        </div>

        <button 
          type="button"
          onClick={(e) => { e.stopPropagation(); decrement(); }}
          className="text-white/30 hover:text-purple-400 p-1 transition-colors z-20 cursor-pointer"
        >
          <svg className="w-3.5 h-3.5" fill="none" viewBox="0 0 24 24" stroke="currentColor">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M19 9l-7 7-7-7" />
          </svg>
        </button>
      </div>
    </div>
  );
};

const RenderTextWithTags = ({ text }: { text: string }) => {
  if (!text) return null;
  const parts = text.split(/(\s+)/);
  return (
    <>
      {parts.map((part, i) => {
        if (part.startsWith("@") && part.length > 1) {
          const nameToDisplay = part.substring(1).replace(/_/g, " ");
          return (
            <span
              key={i}
              className="text-blue-400 font-bold bg-blue-500/10 px-1 rounded mx-0.5 cursor-pointer hover:bg-blue-500/20 transition-colors"
            >
              @{nameToDisplay}
            </span>
          );
        }
        return <span key={i}>{part}</span>;
      })}
    </>
  );
};

// Firestore does not support nested arrays. This helper flattens or converts them.
const sanitizeForFirestore = (obj: any): any => {
  if (Array.isArray(obj)) {
    return obj.map(item => {
      if (Array.isArray(item)) {
        // Convert nested array to object map
        const objForm: any = {};
        item.forEach((subItem, idx) => {
          objForm[`_${idx}`] = sanitizeForFirestore(subItem);
        });
        return objForm;
      } else if (item !== null && typeof item === 'object') {
        return sanitizeForFirestore(item);
      }
      return item;
    });
  } else if (obj !== null && typeof obj === 'object') {
    const newObj: any = {};
    for (const key in obj) {
      // Don't modify specialized firestore objects like Timestamps but do sanitize standard data
      if (obj[key]?.toDate && typeof obj[key].toDate === 'function') {
         newObj[key] = obj[key];
      } else {
         newObj[key] = sanitizeForFirestore(obj[key]);
      }
    }
    return newObj;
  }
  return obj;
};


// Web Audio API custom soundtrack synthesizer for Excellence Diaries (Success story ambient study tracks)
let storyAudioCtx: AudioContext | null = null;
let storySynthGain: GainNode | null = null;
let storySequenceInterval: any = null;

const stopStoryAudio = () => {
  if (storySequenceInterval) {
    clearInterval(storySequenceInterval);
    storySequenceInterval = null;
  }
  if (storySynthGain) {
    try {
      storySynthGain.gain.setValueAtTime(storySynthGain.gain.value, 0);
      storySynthGain.gain.exponentialRampToValueAtTime(0.0001, 0.2);

      setTimeout(() => {
        if (storySynthGain) {
          storySynthGain.disconnect();
          storySynthGain = null;
        }
      }, 250);
    } catch (e) {}
  }
};

const playStoryAudio = (trackName: string) => {
  stopStoryAudio();
  if (!trackName || trackName === "none") return;

  try {
    const AudioContextClass =
      window.AudioContext || (window as any).webkitAudioContext;
    if (!AudioContextClass) return;

    if (!storyAudioCtx) {
      storyAudioCtx = new AudioContextClass();
    }

    // Always attempt to resume in case it's suspended
    if (storyAudioCtx.state === "suspended") {
      storyAudioCtx.resume().catch(() => {});
    }

    storySynthGain = storyAudioCtx.createGain();
    storySynthGain.gain.setValueAtTime(0.08, storyAudioCtx.currentTime); // Low background volume
    storySynthGain.connect(storyAudioCtx.destination);

    let step = 0;
    let notes: number[] = [];

    if (trackName === "heroes") {
      // عزيمة الأبطال: ascending hopeful study melody (C4, D4, E4, G4, A4, C5)
      notes = [261.63, 293.66, 329.63, 392.0, 440.0, 523.25];
    } else if (trackName === "study") {
      // هدوء العباقرة: peaceful alpha state chords
      notes = [220.0, 277.18, 329.63, 440.0];
    } else if (trackName === "victory") {
      // نغم النجاح العظيم: grand brassy arpeggios
      notes = [329.63, 392.0, 523.25, 659.25, 523.25, 392.0];
    } else {
      return;
    }

    const playNote = (
      freq: number,
      duration: number,
      type: "sine" | "triangle" | "sawtooth",
    ) => {
      if (!storyAudioCtx || !storySynthGain) return;
      try {
        const osc = storyAudioCtx.createOscillator();
        const noteGain = storyAudioCtx.createGain();

        osc.type = type;
        osc.frequency.setValueAtTime(freq, storyAudioCtx.currentTime);

        noteGain.gain.setValueAtTime(0.08, storyAudioCtx.currentTime);
        noteGain.gain.exponentialRampToValueAtTime(
          0.0001,
          storyAudioCtx.currentTime + duration,
        );

        osc.connect(noteGain);
        noteGain.connect(storySynthGain);

        osc.start();
        osc.stop(storyAudioCtx.currentTime + duration);
      } catch (err) {}
    };

    // Synthesizer sequencer
    storySequenceInterval = setInterval(
      () => {
        if (!storyAudioCtx || storyAudioCtx.state === "suspended") {
          storyAudioCtx?.resume();
        }

        if (trackName === "heroes") {
          const note = notes[step % notes.length];
          playNote(note, 0.7, "sine");
          if (step % 3 === 0) {
            playNote(note / 2, 1.4, "triangle"); // bass track
          }
        } else if (trackName === "study") {
          const chord = [
            notes[step % notes.length],
            notes[(step + 2) % notes.length],
          ];
          chord.forEach((n) => playNote(n, 2.0, "sine"));
        } else if (trackName === "victory") {
          const note = notes[step % notes.length];
          playNote(note, 0.45, "triangle");
          if (step % 4 === 0) {
            playNote(note * 1.5, 0.3, "sine");
          }
        }
        step++;
      },
      trackName === "victory" ? 450 : trackName === "study" ? 1400 : 550,
    );
  } catch (err) {
    console.warn("Web Audio Context not initialized:", err);
  }
};

