// Helper to push social notifications
export const pushSocialNotification = async (
  recipientUserId: string | null,
  recipientName: string | null,
  senderName: string,
  senderPhoto: string | null,
  type: string,
  postContent: string,
) => {
  if (!recipientUserId && !recipientName) return;
  try {
    await addDoc(collection(db, "social_notifications"), {
      recipientUserId: recipientUserId || null,
      recipientName: recipientName || null,
      senderName,
      senderPhoto,
      type,
      postContent,
      timestamp: serverTimestamp(),
      read: false,
    });
  } catch (err) {
    console.error("Failed to push social notification", err);
  }
};

