const VideoComments = ({ lessonId, isTeacher }: { lessonId: string, isTeacher: boolean }) => {
  const [comments, setComments] = useState<any[]>([]);
  const [newComment, setNewComment] = useState("");
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    import("firebase/firestore").then(({ collection, query, where, orderBy, onSnapshot }) => {
      import("../lib/firebase").then(({ db }) => {
        const q = query(
          collection(db, "video_comments"),
          where("lessonId", "==", lessonId),
          orderBy("timestamp", "asc")
        );
        const unsubscribe = onSnapshot(q, (snap) => {
          const list = snap.docs.map(doc => ({ id: doc.id, ...doc.data() }));
          setComments(list);
          setLoading(false);
        }, (err) => {
          console.error(err);
          setLoading(false);
        });
        return unsubscribe;
      });
    });
  }, [lessonId]);

  const handleSubmit = async () => {
    if (!newComment.trim()) return;
    try {
      const { collection, addDoc } = await import("firebase/firestore");
      const { db } = await import("../lib/firebase");
      
      const currentUserName = typeof window !== 'undefined' ? localStorage.getItem("userProfileName") || "مستخدم" : "مستخدم";
      
      await addDoc(collection(db, "video_comments"), {
        lessonId,
        text: newComment,
        authorName: currentUserName,
        isTeacher,
        timestamp: new Date()
      });
      setNewComment("");
    } catch(e) {
      console.error(e);
    }
  };

  return (
    <div className="space-y-4">
      <h3 className="text-xs font-black text-amber-400 border-b border-white/5 pb-2">
        تعليقات وأسئلة الفرسان
      </h3>
      
      <div className="space-y-3 max-h-[300px] overflow-y-auto no-scrollbar pb-4 pr-1">
        {loading ? (
          <div className="text-center py-4">
            <RefreshCw className="animate-spin mx-auto text-white/20" size={20} />
          </div>
        ) : comments.length === 0 ? (
          <p className="text-center text-[10px] font-bold text-white/30 py-6">
            لا توجد تعليقات حتى الآن. كن أول من يطرح سؤالاً!
          </p>
        ) : (
          comments.map(c => (
            <div key={c.id} className={`p-3 rounded-xl border ${c.isTeacher ? 'bg-[#00E5FF]/5 border-[#00E5FF]/20' : 'bg-black/40 border-white/5'}`}>
              <div className="flex items-center gap-2 mb-1.5">
                <span className={`text-[10px] font-black ${c.isTeacher ? 'text-[#00E5FF]' : 'text-amber-400'}`}>
                  {c.authorName} {c.isTeacher && <span className="bg-[#00E5FF]/10 text-[#00E5FF] px-1 rounded ml-1 text-[8px]">أستاذ</span>}
                </span>
                <span className="text-[8px] text-white/20 font-mono">
                  {c.timestamp?.toDate ? c.timestamp.toDate().toLocaleTimeString([], {hour: '2-digit', minute:'2-digit'}) : ''}
                </span>
              </div>
              <p className="text-white/80 text-[11px] font-bold leading-relaxed">{c.text}</p>
            </div>
          ))
        )}
      </div>

      <div className="flex gap-2">
        <input 
          type="text" 
          value={newComment}
          onChange={e => setNewComment(e.target.value)}
          placeholder={isTeacher ? "أضف رداً أو توضيحاً للطلبة..." : "اطرح سؤالك أو شارك ملاحظتك حول المحاضرة..."}
          className="flex-1 bg-black/60 border border-white/10 rounded-xl px-3 text-xs text-white placeholder-white/30 focus:border-amber-500/50 outline-none transition-colors h-10"
          onKeyDown={e => { if(e.key === 'Enter') handleSubmit(); }}
        />
        <button 
          onClick={handleSubmit}
          disabled={!newComment.trim()}
          className="h-10 px-4 bg-amber-500 disabled:opacity-50 hover:bg-amber-400 text-black font-black text-xs rounded-xl transition-colors cursor-pointer"
        >
          إرسال
        </button>
      </div>
    </div>
  );
};

const PostCommentsSection = ({
  post,
  userProfile,
  showToast,
  onClose,
  currentUserId,
  currentUserName,
  classmates = [],
}: {
  post: any;
  userProfile: any;
  showToast: (msg: string, type?: "success" | "error") => void;
  onClose: () => void;
  currentUserId: string;
  currentUserName: string;
  classmates?: { name: string }[];
}) => {
  const [comments, setComments] = useState<any[]>([]);
  const [reactionUsers, setReactionUsers] = useState<any[]>([]);
  const [selectedReactionFilter, setSelectedReactionFilter] = useState<
    string | null
  >(null);
  const [expandedReplies, setExpandedReplies] = useState<{
    [key: string]: boolean;
  }>({});
  const [commentText, setCommentText] = useState("");
  const [loading, setLoading] = useState(true);
  const [replyTo, setReplyTo] = useState<{ id: string; name: string } | null>(
    null,
  );
  const [activeCommentReactionId, setActiveCommentReactionId] = useState<
    string | null
  >(null);
  const isLocked = post.isLocked || false;

  const [tagSearch, setTagSearch] = useState("");
  const [showTagMenuTarget, setShowTagMenuTarget] = useState<"comment" | null>(
    null,
  );
  const [tagCursorPos, setTagCursorPos] = useState(0);

  const handleTextareaChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const val = e.target.value;
    setCommentText(val);
    const cursor = e.target.selectionStart || 0;
    const textBeforeCursor = val.substring(0, cursor);
    const lastAtPos = textBeforeCursor.lastIndexOf("@");
    if (lastAtPos !== -1) {
      const textAfterAt = textBeforeCursor.substring(lastAtPos + 1);
      if (!textAfterAt.includes(" ") && !textAfterAt.includes("\n")) {
        setTagSearch(textAfterAt);
        setShowTagMenuTarget("comment");
        setTagCursorPos(lastAtPos);
        return;
      }
    }
    setShowTagMenuTarget(null);
  };

  const insertTag = (name: string) => {
    const before = commentText.substring(0, tagCursorPos);
    const searchLen = tagSearch.length;
    const after = commentText.substring(tagCursorPos + 1 + searchLen);
    const formattedName = name.replace(/\s+/g, "_");
    setCommentText(before + "@" + formattedName + " " + after);
    setShowTagMenuTarget(null);
  };

  useEffect(() => {
    const q = query(
      collection(db, "community_posts", post.id, "comments_list"),
      orderBy("timestamp", "asc"),
    );
    const unsubscribe = onSnapshot(
      q,
      (snap) => {
        const list = snap.docs.map((doc) => ({
          id: doc.id,
          ...doc.data(),
        }));
        setComments(list);
        setLoading(false);
      },
      (err) => {
        console.error("Comments subcollection error:", err);
        setLoading(false);
      },
    );
    return () => unsubscribe();
  }, [post.id]);

  useEffect(() => {
    const q = query(
      collection(db, "community_posts", post.id, "reactions_list"),
      orderBy("timestamp", "desc"),
    );
    const unsubscribe = onSnapshot(
      q,
      (snap) => {
        const list = snap.docs.map((doc) => ({
          id: doc.id,
          ...doc.data(),
        }));
        setReactionUsers(list);
      },
      (err) => {
        console.error("Reactions subcollection error:", err);
      },
    );
    return () => unsubscribe();
  }, [post.id]);

  const handleReactToComment = async (commentId: string, sticker: string) => {
    try {
      const commentRef = doc(
        db,
        "community_posts",
        post.id,
        "comments_list",
        commentId,
      );
      await updateDoc(commentRef, {
        [`reactions.${sticker}`]: increment(1),
      });
      setActiveCommentReactionId(null);
    } catch (err) {
      console.error("Error reacting to comment:", err);
    }
  };

  const handleSendComment = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!commentText.trim() || !currentUserId) return;

    if (isLocked) {
      showToast("عذراً، التعليقات مغلقة لهذا المنشور من قبل الإدارة.", "error");
      return;
    }

    if (userProfile && userProfile.canComment === false) {
      alert("تم تقييد صلاحية التعليق لديك من قبل الإدارة.");
      return;
    }

    const textToSubmit = commentText;
    setCommentText("");

    try {
      if (replyTo) {
        const commentRef = doc(
          db,
          "community_posts",
          post.id,
          "comments_list",
          replyTo.id,
        );
        await updateDoc(commentRef, {
          replies: arrayUnion({
            id: Date.now().toString(),
            userId: currentUserId,
            userName: currentUserName,
            userPhotoURL: userProfile?.photoURL || null,
            content: textToSubmit,
            timestamp: new Date().toISOString(),
          }),
        });
        setReplyTo(null);
        showToast("تمت إضافة الرد بنجاح!", "success");
      } else {
        await addDoc(
          collection(db, "community_posts", post.id, "comments_list"),
          {
            userId: currentUserId,
            userName: currentUserName,
            userPhotoURL: userProfile?.photoURL || null,
            content: textToSubmit,
            timestamp: serverTimestamp(),
          },
        );

        const postRef = doc(db, "community_posts", post.id);
        await updateDoc(postRef, {
          comments: increment(1),
        });

        if (post.userId !== currentUserId) {
          pushSocialNotification(
            post.userId,
            null,
            currentUserName,
            userProfile?.photoURL || null,
            "comment",
            post.content || "",
          );
        }

        const matches = textToSubmit.match(/@(\S+)/g);
        if (matches) {
          matches.forEach((m: string) => {
            const name = m.substring(1).replace(/_/g, " ");
            if (name !== currentUserName) {
              pushSocialNotification(
                null,
                name,
                currentUserName,
                userProfile?.photoURL || null,
                "mention_comment",
                textToSubmit,
              );
            }
          });
        }

        showToast("تمت إضافة التعليق بنجاح!", "success");
      }
    } catch (err) {
      console.error("Error adding comment/reply:", err);
      showToast("فشل إضافة التعليق", "error");
    }
  };

  return (
    <div className="fixed inset-0 z-[9999] bg-[#050A18] flex flex-col animate-in fade-in slide-in-from-bottom-5 duration-300">
      {/* Header */}
      <div className="h-16 bg-[#101935] border-b border-white/10 flex items-center justify-between px-4 shrink-0">
        <button
          onClick={onClose}
          className="w-10 h-10 rounded-full bg-white/5 hover:bg-white/10 flex items-center justify-center transition-colors"
        >
          <X size={20} className="text-white/80" />
        </button>
        <span className="text-white font-black">التعليقات والتفاعلات</span>
        <div className="w-10" />
      </div>

      {/* Reactions Overview Header */}
      {((post.reactions && Object.keys(post.reactions).length > 0) ||
        reactionUsers.length > 0) && (
        <div
          className="bg-[#101935]/80 border-b border-white/5 px-4 py-3 shrink-0"
          dir="rtl"
        >
          <div className="flex items-center gap-2 overflow-x-auto no-scrollbar pb-1">
            <button
              onClick={() => setSelectedReactionFilter(null)}
              className={`flex items-center gap-1.5 px-2.5 py-1 rounded-full shrink-0 transition-colors border ${selectedReactionFilter === null ? "bg-[#00E5FF]/20 border-[#00E5FF]/50 text-white" : "bg-white/5 border-white/10 text-white/70 hover:bg-white/10"}`}
            >
              <span className="text-xs font-bold">الكل</span>
            </button>
            {Object.entries(post.reactions || {}).map(([key, val]) => {
              if (val === 0) return null;
              const isSelected = selectedReactionFilter === key;
              return (
                <button
                  key={key}
                  onClick={() => setSelectedReactionFilter(key)}
                  className={`flex items-center gap-1.5 px-2.5 py-1 rounded-full shrink-0 transition-colors border ${isSelected ? "bg-[#00E5FF]/20 border-[#00E5FF]/50" : "bg-white/5 border-white/10 hover:bg-white/10"}`}
                >
                  <span className="text-sm">{key}</span>
                  <span className="text-xs text-white/90 font-bold">
                    {val as number}
                  </span>
                </button>
              );
            })}
          </div>
        </div>
      )}

      {/* Main Content Area: Comments or Reacting Users */}
      <div className="flex-1 overflow-y-auto p-4 space-y-4 no-scrollbar">
        {selectedReactionFilter ? (
          // View Reacting Users List
          <div className="space-y-3" dir="rtl">
            {reactionUsers
              .filter((u) => u.sticker === selectedReactionFilter)
              .map((u) => (
                <div
                  key={u.id}
                  className="flex items-center gap-3 bg-white/[0.02] p-3 rounded-2xl border border-white/5 shadow-sm"
                >
                  <div className="w-10 h-10 rounded-xl overflow-hidden shrink-0 bg-white/5 border border-white/10 flex items-center justify-center">
                    {u.photoURL ? (
                      <img
                        src={u.photoURL}
                        alt=""
                        className="w-full h-full object-cover"
                      />
                    ) : (
                      <User size={20} className="text-white/40" />
                    )}
                  </div>
                  <div className="flex-1">
                    <span className="text-white font-bold text-sm block">
                      {u.name}
                    </span>
                  </div>
                  <div className="shrink-0 flex items-center justify-center w-8 h-8 bg-white/5 rounded-full border border-white/10 shadow-inner">
                    <span className="text-lg leading-none">{u.sticker}</span>
                  </div>
                </div>
              ))}
            {reactionUsers.filter((u) => u.sticker === selectedReactionFilter)
              .length === 0 && (
              <div className="text-center text-white/30 text-xs py-8">
                لا يوجد متفاعلين بهذا الملصق
              </div>
            )}
          </div>
        ) : loading ? (
          <div className="flex items-center justify-center h-full text-white/30 text-xs font-bold">
            جاري تحميل التعليقات...
          </div>
        ) : comments.length === 0 ? (
          <div className="flex flex-col items-center justify-center h-full text-white/20">
            <MessageCircle size={40} className="mb-3 opacity-50" />
            <span className="text-sm font-black">لا توجد تعليقات بعد</span>
            <span className="text-xs">كن أول من يعلق! ✨</span>
          </div>
        ) : (
          comments.map((comment) => (
            <div
              key={comment.id}
              className="flex gap-3 items-start text-right"
              dir="rtl"
            >
              <div className="w-10 h-10 rounded-xl bg-white/5 border border-white/10 flex items-center justify-center shrink-0 overflow-hidden shadow-lg">
                {comment.userPhotoURL ? (
                  <img
                    src={comment.userPhotoURL}
                    alt=""
                    className="w-full h-full object-cover"
                  />
                ) : (
                  <User size={20} className="text-white/40" />
                )}
              </div>
              <div className="flex-1">
                <div className="bg-[#101935] rounded-2xl px-4 py-3 border border-white/5 shadow-md inline-block min-w-[60%] relative">
                  <div className="flex flex-col mb-1.5">
                    <span className="text-[#00E5FF] font-black text-xs">
                      {comment.userName}
                    </span>
                  </div>
                  <p className="text-white/90 text-[13px] leading-relaxed break-words whitespace-pre-wrap">
                    <RenderTextWithTags text={comment.content} />
                  </p>

                  {/* Inline comment reactions */}
                  {comment.reactions &&
                    Object.keys(comment.reactions).length > 0 && (
                      <div className="absolute -bottom-2 -left-2 flex items-center gap-1 bg-[#050A18] border border-white/10 px-1.5 py-0.5 rounded-full shadow-lg">
                        {Object.keys(comment.reactions).map((sticker) => (
                          <span key={sticker} className="text-xs">
                            {sticker}
                          </span>
                        ))}
                        <span className="text-[10px] text-white/50 font-bold ml-1">
                          {
                            Object.values(comment.reactions).reduce(
                              (a: any, b: any) => a + b,
                              0,
                            ) as number
                          }
                        </span>
                      </div>
                    )}
                </div>
                <div className="mt-1 mr-2 flex items-center gap-3 relative">
                  <span className="text-[10px] text-white/30 font-bold">
                    {comment.timestamp?.toDate
                      ? comment.timestamp
                          .toDate()
                          .toLocaleTimeString("ar-IQ", {
                            hour: "numeric",
                            minute: "2-digit",
                          })
                      : "الآن"}
                  </span>
                  {!isLocked && (
                    <>
                      <button
                        onClick={() =>
                          setReplyTo({ id: comment.id, name: comment.userName })
                        }
                        className="text-[10px] font-bold text-white/50 hover:text-white transition-colors cursor-pointer"
                      >
                        رد
                      </button>
                      <button
                        onClick={() =>
                          setActiveCommentReactionId(
                            activeCommentReactionId === comment.id
                              ? null
                              : comment.id,
                          )
                        }
                        className="text-[10px] font-bold text-white/50 hover:text-[#00E5FF] transition-colors cursor-pointer"
                      >
                        تفاعل
                      </button>
                    </>
                  )}

                  {/* Comment Reaction Popover */}
                  {activeCommentReactionId === comment.id && (
                    <div className="absolute top-full mt-1 right-0 z-50 flex items-center gap-1 bg-[#101935] border border-white/10 p-1.5 rounded-2xl shadow-xl">
                      {["❤️", "👍", "💡", "👏", "🔥"].map((sticker) => (
                        <button
                          key={sticker}
                          onClick={() =>
                            handleReactToComment(comment.id, sticker)
                          }
                          className="text-lg hover:scale-125 transition-transform"
                        >
                          {sticker}
                        </button>
                      ))}
                    </div>
                  )}
                </div>

                {/* Replies */}
                {comment.replies && comment.replies.length > 0 && (
                  <div className="mt-2">
                    {!expandedReplies[comment.id] ? (
                      <button
                        onClick={() =>
                          setExpandedReplies((prev) => ({
                            ...prev,
                            [comment.id]: true,
                          }))
                        }
                        className="text-white/50 hover:text-white text-[11px] font-bold flex items-center gap-1 transition-colors"
                      >
                        <div className="w-6 h-[1px] bg-white/20"></div>
                        {comment.replies.length === 1
                          ? "عرض رد واحد"
                          : `عرض ${comment.replies.length} ردود`}
                      </button>
                    ) : (
                      <div className="space-y-3 mt-3">
                        {comment.replies.map((reply: any) => (
                          <div
                            key={reply.id}
                            className="flex gap-2 items-start"
                          >
                            <div className="w-8 h-8 rounded-lg bg-white/5 border border-white/10 flex items-center justify-center shrink-0 overflow-hidden">
                              {reply.userPhotoURL ? (
                                <img
                                  src={reply.userPhotoURL}
                                  alt=""
                                  className="w-full h-full object-cover"
                                />
                              ) : (
                                <User size={16} className="text-white/40" />
                              )}
                            </div>
                            <div className="flex-1">
                              <div className="bg-[#0c1427] rounded-2xl px-3 py-2 border border-white/5 shadow-inner inline-block">
                                <span className="text-[#00E5FF] font-black text-[11px] block">
                                  {reply.userName}
                                </span>
                                <p className="text-white/80 text-xs leading-relaxed mt-0.5 whitespace-pre-wrap">
                                  <RenderTextWithTags text={reply.content} />
                                </p>
                              </div>
                            </div>
                          </div>
                        ))}
                        <button
                          onClick={() =>
                            setExpandedReplies((prev) => ({
                              ...prev,
                              [comment.id]: false,
                            }))
                          }
                          className="text-white/40 hover:text-white text-[10px] font-bold flex items-center gap-1 transition-colors mt-1"
                        >
                          إخفاء الردود
                        </button>
                      </div>
                    )}
                  </div>
                )}
              </div>
            </div>
          ))
        )}
      </div>

      {isLocked ? (
        <div
          className="bg-[#101935] border-t border-rose-500/20 p-6 shrink-0 flex items-center justify-center"
          dir="rtl"
        >
          <div className="flex items-center gap-2 text-rose-400 font-bold text-xs bg-rose-500/10 px-4 py-2 rounded-full border border-rose-500/20">
            <Lock size={14} />
            <span>لقد قامت الإدارة بقفل التعليقات على هذا المنشور.</span>
          </div>
        </div>
      ) : (
        /* Write Comment Form */
        <div
          className="bg-[#101935] border-t border-white/10 p-4 shrink-0"
          dir="rtl"
        >
          {replyTo && (
            <div className="max-w-2xl mx-auto mb-2 flex items-center justify-between bg-white/5 px-3 py-1.5 rounded-lg border border-white/10">
              <span className="text-xs text-white/60">
                الرد على{" "}
                <span className="font-bold text-[#00E5FF]">{replyTo.name}</span>
              </span>
              <button
                type="button"
                onClick={() => setReplyTo(null)}
                className="text-white/40 hover:text-white"
              >
                <X size={14} />
              </button>
            </div>
          )}
          <form
            onSubmit={handleSendComment}
            className="flex gap-3 items-center max-w-2xl mx-auto relative"
          >
            <input
              type="text"
              value={commentText}
              onChange={handleTextareaChange}
              placeholder={replyTo ? "اكتب ردك..." : "اكتب تعليقاً..."}
              className="flex-1 bg-black/40 border border-white/10 rounded-full pl-12 pr-5 py-3.5 text-white text-sm focus:outline-none focus:border-[#00E5FF]/50 transition-colors placeholder:text-white/30 font-bold"
            />
            {showTagMenuTarget === "comment" &&
              classmates.map((c) => c.name).filter((n) => n.includes(tagSearch))
                .length > 0 && (
                <div className="absolute bottom-full left-0 mb-2 max-h-40 overflow-y-auto bg-[#101935] border border-blue-500/30 rounded-xl shadow-[0_-10px_40px_rgba(0,0,0,0.5)] z-[60] w-64 text-right">
                  {classmates
                    .filter((c) => c.name.includes(tagSearch))
                    .map((c, i) => (
                      <button
                        key={i}
                        type="button"
                        onClick={() => insertTag(c.name)}
                        className="w-full text-right px-4 py-2 text-white/90 hover:bg-blue-500/20 font-bold border-b border-white/5 last:border-0 hover:text-blue-400 text-sm cursor-pointer"
                      >
                        {c.name}
                      </button>
                    ))}
                </div>
              )}
            <button
              type="submit"
              disabled={!commentText.trim()}
              className="absolute left-1.5 top-1.5 bottom-1.5 w-10 disabled:opacity-50 disabled:bg-white/5 bg-[#00E5FF] hover:bg-cyan-400 text-black rounded-full flex items-center justify-center transition-all cursor-pointer disabled:cursor-not-allowed"
            >
              <Send size={16} className="mr-0.5" />
            </button>
          </form>
        </div>
      )}
    </div>
  );
};

const RevealBlock: React.FC<{ label: string; text: string }> = ({ label, text }) => {
  const [revealed, setRevealed] = useState(false);
  return (
    <div className="mt-3">
      <button
        onClick={() => setRevealed(!revealed)}
        className="w-full flex items-center justify-between p-3 rounded-xl bg-amber-500/5 hover:bg-amber-500/10 border border-amber-500/10 hover:border-amber-500/20 text-right text-[11px] font-black text-amber-300 transition-all cursor-pointer"
      >
        <span>{label}</span>
        <span className="text-[10px]">{revealed ? "🔼 إخفاء" : "🔽 إظهار"}</span>
      </button>
      <AnimatePresence>
        {revealed && (
          <motion.div
            initial={{ opacity: 0, height: 0 }}
            animate={{ opacity: 1, height: "auto" }}
            exit={{ opacity: 0, height: 0 }}
            className="overflow-hidden mt-2 bg-amber-500/[0.02] border border-amber-500/5 p-4 rounded-xl text-xs font-semibold leading-relaxed text-white/90 font-mono text-right whitespace-pre-line"
          >
            {text}
          </motion.div>
        )}
      </AnimatePresence>
    </div>
  );
};

const getSimulatedFileContent = (title: string, subject: string) => {
  const normSubject = (subject || "").replace(/[أإآ]/g, "ا");
  const normTitle = (title || "").replace(/[أإآ]/g, "ا");

  if (normSubject.includes("عربية") || normTitle.includes("عربية")) {
    return {
      subtitle: "ملخص القواعد الذهبية والوزاريات المرشحة للفرسان",
      sections: [
        {
          heading: "المبحث الأول: تقديم الخبر على المبتدأ وجوباً",
          body: `يُقدَّم الخبر على المبتدأ وجوباً في عدة مواضع لتلافي الأخطاء النحوية والتركيبية، ومن أهمها:
1. إذا كان في المبتدأ ضمير يعود على بعض الخبر: مثل (في الصدقِ نجاتُه). الهاء في (نجاته) تعود على الصدق وهو مضاف إليه الخبر. لو قيل (نجاته في الصدق) لعاد الضمير على متأخر لفظاً ورتبة وهو ممتنع.
2. إذا كان الخبر من الألفاظ التي لها الصدارة في الكلام: مثل أسماء الاستفهام الدالة على الزمان أو المكان أو الحال (متى، أين، كيف)، كقوله تعالى: (يسألونك عن الساعة أيان مرساها).
3. إذا كان الخبر مقصوراً على المبتدأ: بالقصر بـ (إنما) أو بالنفي والاستثناء المفرغ، مثل (إنما عادلٌ اللهُ) أو (ما شاعرٌ إلا المتنبي).`,
          hasReveal: true,
          revealLabel: "اضغط لعرض سؤال وزاري تطبيقي وحله النموذجي 📝",
          revealText: `سؤال وزاري: (في الدارِ صاحبُها). ما حكم تقديم الخبر؟ ولماذا؟
الجواب النموذجي: تقديم الخبر (في الدار) وجوباً، لأن المبتدأ المؤخر (صاحبها) اتصل به ضمير (الهاء) يعود على بعض الخبر وهو الدار.`
        },
        {
          heading: "المبحث الثاني: أساليب النفي الصريحة والضمنية",
          body: `النفي في اللغة العربية نوعان: نفي صريح (ظاهر) ونفي ضمني (غير صريح).
- النفي الصريح: ويتم باستخدام أدوات النفي المخصصة مثل (ليس، ما، لا، لم، لما، لن، إنْ، غير). ولكل أداة تأثير إعرابي وتأثير معنوي يجب الانتباه لهما جيداً في الامتحان الوزاري.
- النفي الضمني: ويتم بأساليب أخرى تفيد النفي بالمعنى دون وجود أداة نفي، وأشهرها: الاستفهام المجازي المتضمن معنى النفي، والشرط غير الجازم بـ (لو، لولا، لوما).`,
          hasReveal: true,
          revealLabel: "اضغط لعرض قاعدة إعرابية هامة لـ (لم ولن) 💡",
          revealText: `فائدة وزارية: (لم) تقلب دلالة المضارع إلى الماضي والزمن معها منقطع وغير متوقع الحصول، أما (لما) فنفيها مستمر إلى الزمن الحاضر والحدث متوقع الحصول. (لن) تنفي المستقبل نفياً مؤكداً بغير قرينة زرقاء.`
        }
      ]
    };
  } else if (normSubject.includes("فيزياء") || normTitle.includes("فيزياء")) {
    return {
      subtitle: "الحقيبة الذهبية للدرجة الكاملة في الفيزياء الوزارية",
      sections: [
        {
          heading: "الفصل الأول: المتسعات العازلة والقوانين الأساسية",
          body: `المتسعة هي جهاز لتخزين الشحنات الكهربائية والطاقة الكهربائية في المجال الكهربائي بين لوحيها.
القانون الأساسي لحساب السعة الكهربائية: C = Q / V.
عند إدخال مادة عازلة ثابت عزلها K بين لوحي متسعة مشحونة ومفصولة:
1. تزداد السعة الكهربائية لتصبح: C_k = K * C.
2. يقل فرق الجهد الكهربائي بنسبة K ليصبح: V_k = V / K.
3. يقل المجال الكهربائي الكهربائي بين اللوحين بنسبة K ليصبح: E_k = E / K.`,
          hasReveal: true,
          revealLabel: "اضغط لإظهار تعليل وزاري مكرر جداً 🔍",
          revealText: `سؤال وزاري: يقل مقدار المجال الكهربائي بين لوحي متسعة مشحونة ومفصولة عند إدخال مادة عازلة؟
الجواب: بسبب تولد مجال كهربائي داخل المادة العازلة (E_d) يعاكس بالاتجاه المجال الكهربائي الخارجي بين اللوحين (E)، فيكون المجال المحصل (E_k = E - E_d) أقل من المجال الأصلي.`
        },
        {
          heading: "المبحث الثاني: قوانين ربط التوالي والتوازي",
          body: `- ربط التوازي: نربط الصفائح المتشابهة معاً. الميزة الأساسية هي ثبوت فرق الجهد (V_total = V1 = V2). السعة المكافئة تزداد (C_eq = C1 + C2)، والهدف هو تخزين شحنة أكبر.
- ربط التوالي: نربط الصفائح المختلفة معاً. الميزة الأساسية هي ثبوت الشحنة (Q_total = Q1 = Q2). السعة المكافئة تقل (1/C_eq = 1/C1 + 1/C2)، والهدف هو تحمل فرق جهد كهربائي أكبر قد لا تتحمله أي متسعة منفردة.`,
          hasReveal: true,
          revealLabel: "اضغط لعرض مثال وزاري سريع للربط ⚡",
          revealText: `مثال: متسعتان سعة الأولى 9μF والثانية 18μF ربطتا على التوالي وسلط جهد 12V.
الشحنة الكلية Q_total = C_eq * V = 6μF * 12V = 72μC. فرق جهد الأولى = 72/9 = 8V، والثانية = 72/18 = 4V.`
        }
      ]
    };
  } else if (normSubject.includes("كيمياء") || normTitle.includes("كيمياء")) {
    return {
      subtitle: "مفكرة المئة درجة في الكيمياء الوزارية الشاملة",
      sections: [
        {
          heading: "الفصل الأول: علم الثرموداينمك وقانون هيس",
          body: `علم الثرموداينمك هو علم يهتم بدراسة الطاقة وتحولاتها ويهدف نحو تحويل أكبر قدر ممكن من الطاقة الحرارية الناتجة من احتراق الوقود إلى طاقة ميكانيكية.
قانون هيس: عند تحويل المتفاعلات إلى نواتج فإن التغير في انثالبي التفاعل هو نفسه سواء تم التفاعل في خطوة واحدة أو في سلسلة من الخطوات.
الفائدة العملية لقانون هيس: حساب انثالبي التفاعلات التي لا يمكن قياسها بشكل مباشر لبطئها الشديد أو لتكون نواتج جانبية غير مرغوب فيها.`,
          hasReveal: true,
          revealLabel: "اضغط لرؤية شروط كتابة المعادلة الحرارية 🧪",
          revealText: `1. يجب ذكر الحالة الفيزيائية للمتفاعلات والنواتج (s, l, g, aq) لأن كمية الحرارة الممتصة أو المنبعثة تتغير بتغير الحالة الفيزيائية.
2. عند ضرب أو قسمة طرفي المعادلة بمعامل معين، يجب إجراء نفس العملية على قيمة الانثالبي ΔH.`
        }
      ]
    };
  } else if (normSubject.includes("انجليزية") || normTitle.includes("انجليزية") || normSubject.includes("english") || normTitle.includes("english")) {
    return {
      subtitle: "English Grammar Mastery & High-Yield Vocab",
      sections: [
        {
          heading: "Unit 1: Past Simple vs Past Continuous",
          body: `We use the Past Continuous to describe a longer, background action in the past. We use the Past Simple for a shorter action that interrupted it.
Formulas:
- Past Continuous: Subject + was/were + Verb-ing.
- Past Simple: Subject + Verb-ed (or irregular second form).
Connectors (while, as, when, and):
1. 'While' and 'As' are followed by the Past Continuous: (While I was eating, the phone rang).
2. 'When' and 'And' are followed by the Past Simple: (I was reading when she called).`,
          hasReveal: true,
          revealLabel: "Click to reveal a Ministerial Grammar Challenge 🇬🇧",
          revealText: `Question: She (tell) us to be quiet as we (make) too much noise. (Correct the verbs)
Answer: She TOLD us to be quiet as we WERE MAKING too much noise. ('as' is followed by past continuous).`
        }
      ]
    };
  } else {
    return {
      subtitle: `حقيبة المنهج الرسمي الشاملة للدرس المتميز: ${title}`,
      sections: [
        {
          heading: "القسم الأول: المفاهيم والأسس النمطية",
          body: `يحتوي هذا الملف المنهجي على الملاحظات المدونة والملخصات الوزارية الذهبية التي تم استخراجها وتدقيقها بنسبة 100% لتطابق النسخة المعتمدة.
يرجى التركيز على المراجعة المركزة للمواضيع الأساسية وحل الأسئلة الملحقة لضمان تحصيل الدرجة الكاملة في الامتحان النهائي.`,
          hasReveal: true,
          revealLabel: "اضغط لعرض وصية أستاذ المادة للتفوق 👑",
          revealText: `التفوق لا يأتي صدفة، بل هو نتاج تنظيم الوقت، والاعتماد على الملخصات المركزة، وحل جميع وزاريات المادة من عام 2015 وحتى العام الحالي بكل دقة وكتابة.`
        }
      ]
    };
  }
};

